  ('services', $cms$[{"id":"brand","icon":"palette","code":"Br","name":"Brand Identity","desc":"Logo systems, type, colour and guidelines that hold up from favicon to billboard.","tags":["Figma","Illustrator","After Effects"],"base":40000},{"id":"uiux","icon":"design_services","code":"Ux","name":"UI/UX Design","desc":"Research, flows and high-fidelity interfaces tested with real users before a line of code.","tags":["Figma","FigJam","Maze"],"base":50000},{"id":"web","icon":"language","code":"Wb","name":"Website Development","desc":"Fast, accessible marketing sites with a CMS your team can actually edit.","tags":["Next.js","Tailwind","Sanity"],"base":60000},{"id":"app","icon":"dashboard","code":"Ap","name":"Web Apps & SaaS","desc":"Dashboards, portals and SaaS products with auth, billing and roles built in.","tags":["React","Node.js","PostgreSQL"],"base":150000},{"id":"mobile","icon":"smartphone","code":"Mb","name":"Mobile Apps","desc":"Cross-platform iOS and Android apps from one codebase, shipped to both stores.","tags":["React Native","Expo","Firebase"],"base":180000},{"id":"ecom","icon":"shopping_cart","code":"Ec","name":"E-commerce","desc":"Storefronts, checkout and inventory flows tuned for conversion and repeat orders.","tags":["Shopify","Stripe","Razorpay"],"base":90000},{"id":"auto","icon":"bolt","code":"Au","name":"Marketing Automation","desc":"Lead capture, nurture sequences and follow-ups that run without anyone pressing send.","tags":["HubSpot","n8n","Mailchimp"],"base":45000},{"id":"crm","icon":"hub","code":"Cr","name":"CRM & Integrations","desc":"Connect forms, payments, sales and support so data moves on its own.","tags":["Zoho","Zapier","REST APIs"],"base":40000},{"id":"cloud","icon":"cloud","code":"Cl","name":"Cloud & DevOps","desc":"Hosting, CI/CD, monitoring and backups set up so releases are uneventful.","tags":["Vercel","AWS","Docker"],"base":35000},{"id":"seo","icon":"travel_explore","code":"Se","name":"SEO & Content","desc":"Technical SEO, content plans and on-page work that compound month after month.","tags":["Search Console","Ahrefs","Webflow"],"base":30000},{"id":"data","icon":"monitoring","code":"An","name":"Analytics & Dashboards","desc":"Event tracking and live dashboards so every decision has a number behind it.","tags":["GA4","Mixpanel","Looker Studio"],"base":40000}]$cms$::jsonb, true),
