  ('funnel', $cms$[{"name":"Attract","desc":"SEO, content and paid campaigns bring the right visitors.","width":100,"icon":"campaign"},{"name":"Capture","desc":"Landing pages and forms turn visits into contacts.","width":88,"icon":"ads_click"},{"name":"Nurture","desc":"Email and WhatsApp sequences build trust automatically.","width":76,"icon":"mail"},{"name":"Qualify","desc":"Lead scoring routes hot leads to sales first.","width":64,"icon":"filter_alt"},{"name":"Convert","desc":"Proposals, checkout and payments with no friction.","width":54,"icon":"payments"},{"name":"Onboard","desc":"Welcome flows and portals get customers to value fast.","width":46,"icon":"waving_hand"},{"name":"Retain","desc":"Reviews, referrals and renewals keep revenue compounding.","width":40,"icon":"autorenew"}]$cms$::jsonb, true),
  ('testimonials', $cms$[{"quote":"They rebuilt our store and the automations behind it in six weeks. Repeat orders went up the month after launch and haven’t come down.","name":"Founder","role":"D2C skincare brand, Mumbai","initials":"SK"},{"quote":"We went from quoting by email to a portal our customers actually use. The team shipped every week and never missed a date.","name":"Head of Operations","role":"B2B logistics company, Pune","initials":"LG"},{"quote":"Gravityy treated our app like their own product. Clear scope, honest estimates and a dashboard that shows us exactly what’s working.","name":"CEO","role":"Fintech startup, Singapore","initials":"FT"}]$cms$::jsonb, true),
  ('pricing', $cms${"india":[{"planId":"build-in","name":"Build Websites","tag":"One-time","desc":"Design and development of a fast, SEO-ready website your team can edit.","price":"₹59,999","unit":"per project","features":["Up to 8 custom-designed pages","CMS setup and training","Mobile-first, Lighthouse 90+","On-page SEO and analytics","30 days post-launch support"],"cta":"Start a website","hi":false},{"planId":"grow-in","name":"Grow","tag":"Monthly","desc":"An ongoing growth team for SEO, automation, analytics and iteration.","price":"₹24,999","unit":"per month","features":["Monthly SEO and content plan","Lead capture and nurture automations","Live analytics dashboard","Conversion experiments","Fortnightly strategy call"],"cta":"Start growing","hi":true}],"intl":[{"planId":"build-global","name":"Build Websites","tag":"One-time","desc":"Design and development of a fast, SEO-ready website your team can edit.","price":"$1,490","unit":"per project","features":["Up to 8 custom-designed pages","CMS setup and training","Mobile-first, Lighthouse 90+","On-page SEO and analytics","30 days post-launch support"],"cta":"Start a website","hi":false},{"planId":"grow-global","name":"Grow","tag":"Monthly","desc":"An ongoing growth team for SEO, automation, analytics and iteration.","price":"$590","unit":"per month","features":["Monthly SEO and content plan","Lead capture and nurture automations","Live analytics dashboard","Conversion experiments","Fortnightly strategy call"],"cta":"Start growing","hi":true}]}$cms$::jsonb, true),
  ('faq', $cms$[{"q":"How long does a typical project take?","a":"A marketing website takes 4–6 weeks. Web apps and mobile apps usually take 8–14 weeks depending on scope. You get a dated plan before we start."},{"q":"How is pricing calculated?","a":"Each service has a base price, adjusted for scope and timeline. The configurator above uses the same logic we use for proposals, so the estimate is a reliable starting point."},{"q":"Do you work with clients outside India?","a":"Yes. Around half our clients are in the US, UK, Europe and Southeast Asia. We bill in USD and overlap at least four hours with your working day."},{"q":"Who owns the code and designs?","a":"You do. Full ownership of code, design files and accounts transfers to you on final payment."},{"q":"What happens after launch?","a":"Every build includes 30 days of support. After that you can move to a Grow plan or a flexible maintenance retainer."},{"q":"Can you work with our existing team or stack?","a":"Yes. We regularly plug into in-house teams, follow your code conventions and work inside your repos and tools."}]$cms$::jsonb, true),
  ('charts', $cms${"weeks":12,"sessions":[2600,2850,2790,3100,3380,3300,3720,3960,4210,4480,4950,5400],"leads":[70,74,78,86,92,95,104,110,118,126,139,150],"channels":{"labels":["Organic","Paid social","Referral","Email","Direct"],"data":[4.2,2.9,6.1,7.9,3.6]},"sources":{"labels":["Organic search","Paid social","Referral","Email","Direct"],"data":[38,24,16,12,10]}}$cms$::jsonb, true),
  ('pages', $cms${"home":{"heroLines":["WE DESIGN.","WE BUILD.","WE AUTOMATE."],"heroSub":"From idea to interface. From code to cloud. From data to growth.","ctaPrimary":"Start a Project","ctaSecondary":"See our work"},"services":{"eyebrow":"11 services · one team","title":"Services","lede":"Everything your digital system needs, under one roof. Pick one, or combine them and see the estimate update live.","metaDescription":"Brand, UI/UX, websites, web apps, mobile apps, e-commerce, automation, CRM, cloud, SEO and analytics — delivered by one team that owns the outcome."},"solutions":{"eyebrow":"Systems, not services","title":"Solutions","lede":"Each engagement is scoped around a business result, then built from the services that get you there, measured end to end.","metaDescription":"Launch systems, lead engines, sales ops, commerce stacks and data layers — engagements scoped around a business result, with live analytics and an engineered growth funnel."},"work":{"eyebrow":"Selected work","title":"Work","lede":"Live client sites and the systems behind them. Open any project to see it running.","metaDescription":"Live projects and case studies by Gravityy Studio: Viara Studios, ATHLEX, D2C commerce, B2B logistics, EdTech and fintech builds, and the results they produced."},"process":{"eyebrow":"How we work","title":"Process","lede":"A fixed, visible process so you always know what ships next, built on tools we know deeply and trust in production.","metaDescription":"Eight steps from idea to scale (discover, define, design, build, automate, launch, measure, scale) on a modern, proven stack."},"pricing":{"eyebrow":"Build & grow","title":"Pricing","lede":"Fixed-price builds and monthly growth plans, priced for India and international clients. Need something custom? Build an estimate below.","metaDescription":"Fixed-price website builds and monthly Grow plans for India (₹) and international (USD) clients, plus a live estimate for any combination of services."},"faq":{"eyebrow":"Help","title":"FAQ","lede":"The things clients usually ask before we start. Can’t find yours? Write to hello@gravityystudio.com.","metaDescription":"Timelines, pricing, international clients, ownership, post-launch support and working with your existing team: answers to common questions about working with Gravityy Studio."},"blog":{"eyebrow":"Growth notes","title":"Blog","lede":"What we learn shipping and growing client systems: design, engineering, automation and analytics.","metaDescription":"Articles from Gravityy Studio on web design, Next.js engineering, marketing automation, CRM integration and analytics."},"contact":{"eyebrow":"Contact","title":"Contact","lede":"Start a project or request a free audit.","metaDescription":"Start a project with Gravityy Studio or request a free audit of your site's speed, SEO and conversion path, with a written report within 3 working days."}}$cms$::jsonb, true),
